// Converts the Claude Design combat effects (data/art/effects.yaml) into the
// game data file data/art/effects.json, and checks its structure. The YAML is
// the source of truth; do not edit effects.json by hand. M4 plays the frames.
import yaml from 'js-yaml';

type Frame = Record<string, unknown>;

interface YamlEffect {
  effect: string;
  total_ms_at_18_cells: number;
  frames: Frame[];
  persist?: Frame;
  loop?: boolean;
  static?: boolean;
}

interface YamlDoc {
  line_sets: Record<string, string[]>;
  patterns: Record<string, unknown[][]>;
  travel: string;
  queue: { stagger_ms: number; stagger_ms_5plus: number; budget_ms: number; scale_if_over: boolean; min_frame_ms: number; skip_key: string };
  colors: Record<string, string>;
  effects: YamlEffect[];
}

export interface EffectDef {
  /** Total time when the path is 18 cells long. */
  totalMsAt18Cells: number;
  frames: Frame[];
  /** What stays on the grid after the effect. */
  persist?: Frame;
  loop?: boolean;
  static?: boolean;
}

export interface EffectsFile {
  source: string;
  lineSets: Record<string, string[]>;
  patterns: Record<string, unknown[][]>;
  travel: string;
  queue: { staggerMs: number; staggerMs5Plus: number; budgetMs: number; scaleIfOver: boolean; minFrameMs: number; skipKey: string };
  colors: Record<string, string>;
  effects: Record<string, EffectDef>;
}

/** Names that a frame uses for line sets and patterns. */
function frameRefs(frame: unknown): { sets: string[]; patterns: string[] } {
  const sets: string[] = [];
  const patterns: string[] = [];
  const visit = (v: unknown): void => {
    if (Array.isArray(v)) return v.forEach(visit);
    if (v === null || typeof v !== 'object') return;
    for (const [k, x] of Object.entries(v)) {
      if (k === 'set' && typeof x === 'string') sets.push(x);
      else if (k === 'pat' && typeof x === 'string') patterns.push(x);
      else visit(x);
    }
  };
  visit(frame);
  return { sets, patterns };
}

/** Reads the YAML text, checks it, and returns the effects.json content. Throws on problems. */
export function convertEffects(yamlText: string): EffectsFile {
  const doc = yaml.load(yamlText) as YamlDoc;
  const header = yamlText.split('\n')[0]?.replace(/^#\s*/, '') ?? '';
  const problems: string[] = [];
  const effects: Record<string, EffectDef> = {};
  for (const [name, set] of Object.entries(doc.line_sets)) {
    if (set.length !== 4) problems.push(`line_sets.${name}: ${set.length} glyphs, need 4 (horizontal, vertical, two diagonals)`);
  }
  for (const e of doc.effects) {
    if (effects[e.effect]) problems.push(`${e.effect}: listed twice`);
    if (!Array.isArray(e.frames) || e.frames.length === 0) problems.push(`${e.effect}: no frames`);
    if (typeof e.total_ms_at_18_cells !== 'number' || e.total_ms_at_18_cells < 0) problems.push(`${e.effect}: bad total_ms_at_18_cells`);
    for (const [i, f] of (e.frames ?? []).entries()) {
      const travel = f.travel as { ms?: unknown } | undefined;
      const ms = typeof f.ms === 'number' ? f.ms : travel?.ms;
      if (typeof ms !== 'number' || ms < 0) problems.push(`${e.effect}.frames[${i}]: no time (ms)`);
    }
    for (const f of [...(e.frames ?? []), ...(e.persist ? [e.persist] : [])]) {
      const refs = frameRefs(f);
      for (const s of refs.sets) if (!doc.line_sets[s]) problems.push(`${e.effect}: unknown line set "${s}"`);
      for (const p of refs.patterns) if (!doc.patterns[p]) problems.push(`${e.effect}: unknown pattern "${p}"`);
    }
    effects[e.effect] = {
      totalMsAt18Cells: e.total_ms_at_18_cells,
      frames: e.frames,
      ...(e.persist ? { persist: e.persist } : {}),
      ...(e.loop ? { loop: true } : {}),
      ...(e.static ? { static: true } : {}),
    };
  }
  if (problems.length > 0) throw new Error(`effects.yaml has problems:\n  ${problems.join('\n  ')}`);
  const q = doc.queue;
  return {
    source: `data/art/effects.yaml (${header}). Generated by tools/import-art.ts. Do not edit.`,
    lineSets: doc.line_sets,
    patterns: doc.patterns,
    travel: doc.travel,
    queue: {
      staggerMs: q.stagger_ms,
      staggerMs5Plus: q.stagger_ms_5plus,
      budgetMs: q.budget_ms,
      scaleIfOver: q.scale_if_over,
      minFrameMs: q.min_frame_ms,
      skipKey: q.skip_key,
    },
    colors: doc.colors,
    effects,
  };
}

/** The exact text of data/art/effects.json for a YAML text. */
export function effectsJson(yamlText: string): string {
  return `${JSON.stringify(convertEffects(yamlText), null, 2)}\n`;
}
